import { createHash, randomBytes, timingSafeEqual } from "node:crypto"

// Control-channel authentication. The token is generated by the sidecar's parent
// (the agent core) and handed over at spawn, so it is never written to disk and
// never visible to other principals. Comparison is timing-safe.

export function generateToken() {
  return randomBytes(32).toString("hex")
}

export function tokensMatch(received: string, expected: string) {
  const a = createHash("sha256").update(received, "utf8").digest()
  const b = createHash("sha256").update(expected, "utf8").digest()
  return timingSafeEqual(a, b)
}
